import{c as t,Q as r,j as o,m as n}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"Club Registry","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/club-registry.md","filePath":"user/reference/club-registry.md"}'),s={name:"user/reference/club-registry.md"};function a(i,e,l,h,d,u){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="club-registry" tabindex="-1">Club Registry <a class="header-anchor" href="#club-registry" aria-label="Permalink to &quot;Club Registry&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers maintaining the shared list of clubs across events.</p><p>The <em>Club Registry</em> is meshO Manager&#39;s master list of clubs, shared by every event on this server. Enter a club once — its name, short name, and logo — and it&#39;s recognised in every future event, so competitors&#39; club details and logos stay consistent without re-typing.</p><p>It&#39;s one of the pages under <strong>Settings → Global registry</strong>, alongside the <a href="./competitor-registry">Competitor Registry</a> and the <a href="./../running-the-event/hire-items">Hire card registry</a>.</p><p>A new installation doesn&#39;t start empty: Manager comes with a list of clubs, short names and logos already filled in, copied into the registry the first time it runs. From then on the registry is yours — later updates never replace it.</p><h2 id="why-clubs-are-global" tabindex="-1">Why clubs are global <a class="header-anchor" href="#why-clubs-are-global" aria-label="Permalink to &quot;Why clubs are global&quot;">​</a></h2><p>Clubs live in the registry, not inside a single event. Enter &quot;Red Roos&quot; once and every future event recognises it, with the same short name and logo. Each event keeps its own copy of the clubs its competitors use, merged on top of the shared registry — so a tweak you make for one event doesn&#39;t leak into the others. Because of this, you <strong>add and edit clubs here, not on an event&#39;s Clubs page</strong>. See <a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a>.</p><p><strong>A country added later still reaches your events.</strong> If an event already has a club that had no country (or no organisation type) when it was added, it picks one up as soon as the registry has it. That happens when you save the club here, when an Eventor refresh brings it in, when you open the event, and when it&#39;s started or resumed. This only ever fills a blank: a country the event already holds is left alone, even if the registry now says something different. Events dated before today, and events that are complete or abandoned, are left exactly as they were published.</p><h2 id="open-the-club-registry" tabindex="-1">Open the Club Registry <a class="header-anchor" href="#open-the-club-registry" aria-label="Permalink to &quot;Open the Club Registry&quot;">​</a></h2><p>In <strong>Settings</strong>, under <strong>Global registry</strong>, choose <strong>Club registry</strong>. The count beside the search box shows how many clubs the registry holds (<strong>Showing 4 of 536</strong> while a search narrows it).</p><h2 id="what-s-in-the-list" tabindex="-1">What&#39;s in the list <a class="header-anchor" href="#what-s-in-the-list" aria-label="Permalink to &quot;What&#39;s in the list&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Logo</strong></td><td>The club&#39;s logo, shown on result screens.</td></tr><tr><td><strong>Club</strong></td><td>Full club name. Click it to edit the club.</td></tr><tr><td><strong>Short name</strong></td><td>The abbreviated name used where space is tight.</td></tr><tr><td><strong>Country</strong></td><td>Three-letter country code (ISO 3166-1 alpha-3, for example <code>AUS</code>).</td></tr><tr><td><strong>External ID</strong></td><td>The club&#39;s number in the system it&#39;s registered with — for a club from Eventor, its Eventor organisation number. Blank for a club Eventor doesn&#39;t know.</td></tr><tr><td><strong>Provider</strong></td><td>Who gave the club that number: <strong>Eventor</strong>, or blank.</td></tr></tbody></table><p>Drag a column heading by its grip to reorder the columns, and use the <strong>Columns</strong> menu to hide the ones you don&#39;t need.</p><p><strong>Why External ID matters.</strong> When you upload results or a start list to Eventor (or send it an IOF XML file), meshO includes a club&#39;s ID only when its provider is <strong>Eventor</strong>. Eventor credits a result to whichever organisation that number belongs to and never matches a club by name. So a school or club Eventor doesn&#39;t know is sent by name alone, and its runners&#39; results are accepted without being linked to any club, rather than being credited to an unrelated club that happens to have the same number.</p><p>Use <strong>Search clubs</strong> to filter by full or short name.</p><h2 id="add-and-edit-clubs" tabindex="-1">Add and edit clubs <a class="header-anchor" href="#add-and-edit-clubs" aria-label="Permalink to &quot;Add and edit clubs&quot;">​</a></h2><p>From the <strong>Actions</strong> menu:</p><ul><li><strong>Add club…</strong> — enter the club&#39;s name, short name, and country.</li><li><strong>Clear club registry…</strong> — removes every club from the registry, after you confirm. Events keep their own clubs, and the short names and logos you set are remembered for when a club comes back (for example after the next Eventor refresh). This can&#39;t be undone.</li></ul><p>Click a club&#39;s name to open <strong>Edit club</strong>, where you can change its <strong>Short name</strong> (required), <strong>Country</strong>, <strong>External ID</strong>, <strong>ID provider</strong> and <strong>Club logo</strong>, or delete it. Deleting a club from the registry doesn&#39;t affect any event.</p><p><strong>Linking a club to Eventor.</strong> If a school or club you added yourself has since joined Eventor, enter its Eventor organisation number as <strong>External ID</strong> and <code>Eventor</code> as <strong>ID provider</strong>. Events that hold the club and have no ID for it yet pick the link up. A club that came from Eventor keeps the number Eventor gave it; you can&#39;t change it here. Removing a link only affects events that add the club afterwards.</p><p><strong>Clubs an import meets.</strong> When a CSV or IOF XML entry list names a club the registry doesn&#39;t know, meshO adds it here as one of your own clubs, so next year&#39;s event recognises it by name. A club number in a spreadsheet is never treated as an Eventor organisation number unless Eventor gave that number to a club with the same name.</p><p>To set your own logo, choose a file under <strong>Override with a local PNG (max 256x256)</strong>: it must be a PNG no larger than 256 × 256 pixels, and a preview shows it before you save. With Eventor switched on, <strong>Refresh from Eventor</strong> in the same dialog fetches that one club&#39;s logo again — replacing a logo you uploaded, so it goes back to Eventor&#39;s.</p><h2 id="populate-from-eventor" tabindex="-1">Populate from Eventor <a class="header-anchor" href="#populate-from-eventor" aria-label="Permalink to &quot;Populate from Eventor&quot;">​</a></h2><p>If you use Eventor, the <strong>Actions</strong> menu can fill the registry for you. Both items appear only once <strong>Enable Eventor</strong> is switched on and the connection is set up under <strong>Settings → Eventor</strong> (see <a href="./settings#eventor">Settings</a>):</p><ul><li><strong>Refresh clubs from Eventor</strong> — replaces the list with the clubs Eventor knows for the <strong>Organisation ID</strong> in your Eventor settings, and reports how many it loaded. A short name you changed by hand is kept, and so is every club you added yourself or that an import added.</li><li><strong>Fetch default logos from Eventor</strong> — download each club&#39;s logo. A progress bar shows how many have been fetched. A logo you uploaded yourself is never replaced.</li></ul><blockquote><p><strong>Tip:</strong> A club&#39;s <strong>short name</strong> is what most screens display, so set it to something that reads well at a glance — and upload a logo if you want the club&#39;s icon to appear alongside results.</p></blockquote><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a> — how clubs attach to competitors in an event</li><li><a href="./competitor-registry">Competitor Registry</a> — the matching store for people</li><li><a href="./../screens/creating-screens">Creating screens</a> — where club names and logos appear</li><li><a href="./settings">Settings</a></li></ul>',28)])])}const b=t(s,[["render",a]]);export{g as __pageData,b as default};
